cat > <TMP>/harness.js <<'JS'
const fs=require('fs');
const html=fs.readFileSync('/app/index.html','utf8');
if(/https?:\/\/|<img|<link|url\(|@import|src=/.test(html)) { console.error('EXTERNAL_ASSET_FOUND'); process.exit(1); }
const m=html.match(/<script>([\s\S]*?)<\/script>/);
if(!m){console.error('no script');process.exit(1)}
let rafCb=null, rafCount=0;
const grad={addColorStop(){}};
const ctx=new Proxy({},{ get:(t,p)=>{
  if(p==='createRadialGradient'||p==='createLinearGradient') return ()=>grad;
  if(p==='measureText') return ()=>({width:0});
  return typeof p==='string' ? (()=>{}) : undefined;
}, set:()=>true });
const canvas={ getContext:()=>ctx, getBoundingClientRect:()=>({left:0,top:0,width:800,height:600}), addEventListener(){}, width:0,height:0, style:{} };
global.window={ innerWidth:800, innerHeight:600, devicePixelRatio:1, addEventListener(){}, matchMedia:()=>({matches:false, addEventListener(){}}) };
global.document={ getElementById:()=>canvas };
global.requestAnimationFrame=(cb)=>{ rafCb=cb; return ++rafCount; };
global.cancelAnimationFrame=()=>{};
eval(m[1]);
if(!rafCb){console.error('no rAF queued');process.exit(1)}
rafCb(1000); rafCb(2000); rafCb(3500);
console.log('SMOKE_OK frames executed, rAF queued:', !!rafCb);
// reduced-motion path
global.window.matchMedia=()=>({matches:true, addEventListener(){}});
rafCb=null; eval(m[1]); console.log('REDUCED_SMOKE_OK rafQueued=', !!rafCb);
JS
node <TMP>/harness.js; echo "---"; ls -lh /app/index.html; grep -c "http" /app/index.html || true

